questions.solution:
function checkTransfer(from, amount) {
  if (!Number.isInteger(amount) || amount <= 0) return "invalid amount";
  if (from.frozen) return "account frozen";
  if (from.balance < amount) return "insufficient funds";
  return "ok";
}

const account = { balance: 20000, frozen: false };
console.log(checkTransfer(account, -100));
console.log(checkTransfer({ balance: 20000, frozen: true }, 100));
console.log(checkTransfer(account, 20001));
console.log(checkTransfer(account, 20000));
